import java.util.*;
/** Independent exact frozen Source S_Icons plus manual encoder; no live state/SQL/output qualification. */
public final class SourceIcons1Plan {
 static int cases,comparisons;static void check(boolean b,String s){if(!b)throw new AssertionError(s);cases++;}
 static final List<Integer> SKILLS=List.of(78,176,55,163,206,31,134,71,14,56,181,111,133,171,153,155,148,183,193,216,32,191,158,217,211,173,188,175,1017,156,166,174,104,47,167,149);
 static NativeSourceIcons1.Snapshot snapshot(Set<Integer> active,Map<Integer,Integer> seconds,boolean coexist,int override,int duration,long millis){return new NativeSourceIcons1.Snapshot(active,seconds,coexist,override,duration,millis);}
 static void compare(NativeSourceIcons1.Snapshot snapshot){byte[] nativePacket=NativeSourceIcons1.packet(snapshot),source=SourceIcons1Oracle.packet(snapshot.active(),snapshot.seconds(),snapshot.coexist(),snapshot.overrideSkill(),snapshot.overrideSeconds(),snapshot.wallMillis());if(!Arrays.equals(nativePacket,source))throw new AssertionError("exact Source ICONS1 difference at comparison "+comparisons+" input="+snapshot+" native="+java.util.HexFormat.of().formatHex(nativePacket)+" Source="+java.util.HexFormat.of().formatHex(source));comparisons++;}
 static void isolated(){int before=comparisons;int[] times={Integer.MIN_VALUE,-5,-1,0,1,2,3,4,5,7,8,15,16,17,31,32,33,63,64,255,1020,1021,4080,4081,65535,65536,Integer.MAX_VALUE};for(boolean coexist:List.of(false,true))for(int skill:SKILLS)for(int seconds:times){compare(snapshot(Set.of(skill),Map.of(skill,seconds),coexist,0,0,1_793_000_000_123L));compare(snapshot(Set.of(),Map.of(),coexist,skill,seconds,1_793_000_000_123L));}check(comparisons-before==3888,"all36 Source inputs, both coexist modes, 27 boundary durations and active/override branches");}
 static void weapons(){int before=comparisons;var family=List.of(148,155,163,149,156,166);var times=Map.of(148,101,155,102,163,103,149,104,156,105,166,106);for(boolean coexist:List.of(false,true))for(int mask=0;mask<64;mask++){var active=new HashSet<Integer>();for(int i=0;i<6;i++)if((mask&(1<<i))!=0)active.add(family.get(i));compare(snapshot(active,times,coexist,0,0,0));for(int override:family)compare(snapshot(active,times,coexist,override,37,0));}check(comparisons-before==896,"all64 shared weapon combinations and all6 explicit overrides, both coexist modes");}
 static void mixed(){int before=comparisons;var random=new Random(0x3811C0A5L);for(int n=0;n<2048;n++){var active=new HashSet<Integer>();var seconds=new HashMap<Integer,Integer>();for(int skill:SKILLS){if(random.nextBoolean())active.add(skill);seconds.put(skill,random.nextInt(70000)-100);}int override=n%5==0?68:SKILLS.get(random.nextInt(SKILLS.size()));compare(snapshot(active,seconds,random.nextBoolean(),override,random.nextInt(70000)-100,random.nextLong()));}check(comparisons-before==2048,"mixed complete status sets/absent effects/overrides/timestamp/coexist Source comparisons");for(long millis:new long[]{Long.MIN_VALUE,-1001,-1000,-999,0,999,1000,2_147_483_648_000L,4_294_967_296_000L,Long.MAX_VALUE})compare(snapshot(Set.of(),Map.of(),false,0,0,millis));check(true,"Source signed time division and int epoch rollover preserved");}
 static void semantics(){var blank=snapshot(Set.of(),Map.of(),false,0,0,0);byte[] bytes=NativeSourceIcons1.packet(blank);check(bytes.length==210&&(bytes[0]&255)==250&&(bytes[1]&255)==20&&(bytes[2]&255)==204&&bytes[3]==0&&bytes[4]==0&&bytes[5]==0,"Source opcode/ICONS1/204-byte header and fixed210-byte payload");check(Arrays.equals(bytes,NativeSourceIcons1.packet(snapshot(Set.of(),Map.of(148,100),false,0,0,0))),"positive remaining time does not invent an absent active effect");check(!Arrays.equals(bytes,NativeSourceIcons1.packet(snapshot(Set.of(148),Map.of(148,0),false,0,0,0))),"Source active zero-second shared weapon still writes its skill marker");check(Arrays.equals(bytes,NativeSourceIcons1.packet(snapshot(Set.of(),Map.of(),false,68,37,0))),"68 has no ICONS1 slot; dedicated ICON_I2H remains separate");check(!Arrays.equals(bytes,NativeSourceIcons1.packet(snapshot(Set.of(),Map.of(),false,148,37,0))),"Source explicit positive override can fill a slot even without active effect");check(Arrays.equals(bytes,NativeSourceIcons1.packet(snapshot(Set.of(),Map.of(),true,148,37,0))),"coexist proxy prevents legacy shared-slot override");var active=new HashSet<>(Set.of(47,56));var seconds=new HashMap<>(Map.of(47,5,56,31));var frozen=snapshot(active,seconds,false,0,0,0);var original=NativeSourceIcons1.packet(frozen);active.clear();seconds.clear();check(Arrays.equals(original,NativeSourceIcons1.packet(frozen)),"scalar snapshot copies caller maps/sets");boolean rejected=false;try{frozen.seconds().put(47,1);}catch(UnsupportedOperationException e){rejected=true;}check(rejected,"immutable snapshot map");original[14]^=1;check(!Arrays.equals(original,NativeSourceIcons1.packet(frozen)),"caller packet mutation cannot alter future encoding");for(int i=6;i<210;i++){int slot=i-6;if(Set.of(8,9).contains(slot))continue;check(NativeSourceIcons1.packet(frozen)[i]==0,"unrelated/unused Source slot remains zero "+slot);}for(var type:List.of(NativeSourceIcons1.Snapshot.class,NativeSourceIcons1.Rule.class))for(var field:type.getDeclaredFields())check(!Set.of(ClientSession.class,NativePlayerCommit.Frame.class,NativeAreaMaterialAction.Context.class,GameHub.class,NativePlayerLifetime.class).contains(field.getType()),"encoder scalar values confer no actor/Frame/Hub/lifetime/output authority");}
 public static void main(String[]args){check(new HashSet<>(SKILLS).size()==36,"all actual Source ICONS1 scalar status IDs");isolated();weapons();mixed();semantics();check(comparisons==6842,"all independent exact Source comparisons accounted");System.out.println("PASS"+cases+" Source ICONS1 complete-scalar-encoder contracts; exact-Source-comparisons="+comparisons+", status-inputs=36, shared-weapon-combinations=64, coexist-modes=2; live-status-projection/coexist-reader/production-output/OwnCharStatus/Main/memory/backend/game/MySQL remain open");}
}
